import React, { Ref, forwardRef, ReactElement } from 'react';
import { PropsValue, SingleValue } from 'react-select';

import { _VisuallyHidden as VisuallyHidden } from '../../../core/components/visually-hidden/VisuallyHidden.js';
import { _BaseOption } from '../types.js';

//#region Typings
/** Accepted properties for the HiddenSelect component */
export interface HiddenSelectV2Props<OptionValue> {
  ref: Ref<HTMLSelectElement>;
  name?: string;
  selectedValues?: PropsValue<OptionValue>;
  required?: boolean;
}
//#endregion

/** HiddenSelect component */
export const HiddenSelectV2: <OptionValue>(
  props: HiddenSelectV2Props<OptionValue>,
) => /* @__PURE__ */ ReactElement | null = forwardRef(
  /* eslint-disable @typescript-eslint/no-unnecessary-type-constraint */
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  <OptionValue extends any>(
    /* eslint-disable @typescript-eslint/no-unnecessary-type-constraint */
    {
      name,
      selectedValues,
      required,
      ...remainingProps
    }: HiddenSelectV2Props<OptionValue>,
    ref: typeof remainingProps.ref,
  ) => {
    const multiple = Array.isArray(selectedValues);

    let selectedValuesArray: string[] = [];
    if (multiple) {
      selectedValuesArray =
        selectedValues?.length > 0
          ? selectedValues.map((val) => {
              return val.value;
            })
          : [];
    } else {
      selectedValuesArray = selectedValues
        ? [
            `${
              (
                selectedValues as unknown as SingleValue<
                  _BaseOption<OptionValue>
                >
              )?.value
            }`,
          ]
        : [];
    }

    let value: string | string[];
    if (multiple) {
      value = selectedValuesArray;
    } else {
      // use string value or empty string as array values are not allowed for single select
      value = selectedValues
        ? `${
            (selectedValues as unknown as SingleValue<_BaseOption<OptionValue>>)
              ?.value
          }`
        : '';
    }

    return (
      <VisuallyHidden>
        <select
          ref={ref}
          name={name}
          multiple={multiple}
          tabIndex={-1}
          required={required}
          aria-hidden
          onChange={() => {
            /** noop */
          }}
          value={value}
        >
          {selectedValuesArray.map((val, key) => {
            return <option value={`${val}`} key={key}></option>;
          })}
        </select>
      </VisuallyHidden>
    );
  },
);

(
  HiddenSelectV2 as typeof HiddenSelectV2 & { displayName: string }
).displayName = 'HiddenSelectV2';
